function asPlain(v) {
  if (v == null) return v;
  if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return v;
  try { return JSON.parse(JSON.stringify(v)); } catch (e) { return String(v); }
}
function errorMessage(err) {
  if (err == null) return null;
  if (typeof err === 'string') return err;
  return err.message || err.description || err.readableMessage || null;
}
function inferService(item) {
  if (item.service && String(item.service).trim()) return String(item.service).trim();
  const node = String(item.parentNode || '');
  const err = item.error;
  const blob = (typeof err === 'string' ? err : JSON.stringify(asPlain(err) || '')).toLowerCase();
  const ctxName = err && err.context && err.context.data && err.context.data.name;
  if (ctxName === 'InsufficientBalanceError' || blob.indexOf('insufficientbalanceerror') !== -1) return 'Jina';
  if (blob.indexOf('openrouter') !== -1) return 'OpenRouter';
  if (node === 'Read listing page' || node === 'Read article page') return 'Jina';
  if (/summarize|classif|llm scraper/i.test(node)) return 'OpenRouter';
  return null;
}
const globals = $('Lookup global variables').first().json;
const offset = Number(globals.display_tz_offset_hours || 0);
const local = $now.plus({ hours: offset });
const fileDate = local.hour >= 20 ? local.plus({ days: 1 }) : local;
const y = fileDate.year;
const m = String(fileDate.month).padStart(2, '0');
const d = String(fileDate.day).padStart(2, '0');
const fileName = '/files/sortedsignals/logs/NODE_ERRORS_' + y + '_' + m + '_' + d + '.json';
const item = $input.first().json;
const record = {
  loggedAt: new Date().toISOString(),
  parentWorkflow: item.parentWorkflow || null,
  parentNode: item.parentNode || null,
  service: inferService(item),
  url: item.url || item.contentURL || item.link || null,
  message: errorMessage(item.error) || item.message || null,
  error: asPlain(item.error || null),
};
return [{ json: { fileName: fileName, line: JSON.stringify(record) + '\n' } }];
